// Extract from File 输出文本在 $json.text 中
// 不做复杂解析，直接输出纯文本作为 CV 信息
const rawText = $json.text || $json.data || '';
if (!rawText) return [{ cvText: 'CV 读取失败，请确认 cv/CV.pdf 文件存在且可读' }];

// 简单清理：去多余空白、截断过长的文本
const cleanText = rawText.replace(/\s+/g, ' ').trim();
const maxLen = 30000;
const cvText = cleanText.length > maxLen ? cleanText.substring(0, maxLen) + '...' : cleanText;

return [{ cvText: cvText }];

// Pipeline gate: drop internships/students, then everything defence/military.
// Two independent layers: company blocklist + text signals (title + description).
const data = typeof $json === 'string' ? JSON.parse($json) : $json;
const jobs = (data && data.jobs) || [];
const srcStats = (data && data.stats) || {};

const STUDENT = [/student/i, /intern(ship)?\b/i, /werkstudent/i, /praktik(ant|um)/i,
                 /thesis/i, /(bachelor|master)arbeit/i, /ausbildung/i, /dual(es)? studium/i, /\bhiwi\b/i];

// Companies whose roles are military/defence by definition (citizenship-restricted work).
const DEFENSE_COMPANY = [
  /rheinmetall/i, /diehl\b/i, /hensoldt/i, /knds/i, /krauss-?maffei/i, /wegmann/i, /mbda/i,
  /thales/i, /airbus\s*(defence|ds|defense)/i, /leonardo\s*(drs|defence|uk)?/i, /lockheed/i,
  /raytheon|\brtx\b/i, /northrop/i, /\bbae\s*systems/i, /elbit/i, /l3harris/i, /boeing\s*(defence|defense)/i,
  /saab\s*(ab| defence| bofors)/i, /kongsberg/i, /anduril/i, /helsing/i, /arx\s*robotics/i,
  /quantum-?systems/i, /stark\s*(defence|defense)/i, /donaustahl/i, /bundeswehr/i, /\bbwi\b/i,
  /\biabg\b/i, /\besg\s*(elektronik|gmbh)?/i, /gds?els/i, /iveco\s*defence/i, /airborne\s*technologies/i,
  /ffg\s*(gmbh)?|flensburger\s*fahrzeugbau/i, /gl\s*group|global\s*clearance/i, /patria\b/i,
  /naval\s*group/i, /fincantieri/i, /exail/i, /arex\b/i, /whitehead\s*alenia/i, /deutsche\s*panzer/i,
  /general\s*dynamics/i, /leidos/i, /caci\b/i, /booz\s*allen/i, /mitre\b/i, /qinetiq/i,
  /thielert|ontime-?defence/i, /simumatik/i,
];
// Text signals: military/defence context or citizenship/clearance gating.
const DEFENSE_TEXT = [
  /\bdefence\b|\bdefense\b/i, /military|militar/i, /wehrtechnik|wehrtechnisch/i,
  /verteidigung|rüstung|rustung/i, /\bbundeswehr\b/i, /\bnato\b/i, /\bitar\b/i,
  /security\s*clearance|sicherheitsüberprüf|sicherheitsueberpruef|erweitertes?\s*führungszeugnis/i,
  /\b(ü2|ue2|ü3|ue3|sü2|su2|vs-nfd)\b/i, /staatsbürgerschaft|staatsangehörig|citizenship/i,
  /geheim(?!nis)|classified|streng\s*vertraulich/i, /mil-?std|milspec/i,
  /waffensystem|weapon\s*system|munition|\bmissile\b|\brakete\b|panzer\b|fregatte/i,
  /luftverteidigung|air\s*defence|air\s*defense/i, /radar\s*(system|technolog)/i,
  /unbemannte?\s*(system|luftfahrzeug)|\buav\b|\bdrone\s*(defence|defense|war)/i,
  /\bc4isr\b|\bc2\s*system/i, /soldat(en)?\b|troop/i, /verteidigungsministerium|ministry\s*of\s*defence/i,
];

const stats = {
  raw: jobs.length, droppedStudent: 0, droppedDefense: 0, droppedOther: 0,
  defenseExamples: [], statusBySource: {},
  sources: srcStats, errors: (srcStats && srcStats.errors) || [],
};
const seenKeys = new Set();
const result = [];

for (const job of jobs) {
  const title = (job.title || '').trim();
  const company = (job.company || '').trim();
  const desc = (job.description || '').trim();
  const hay = (title + ' ' + company + ' ' + desc).toLowerCase();
  stats.statusBySource[job.site || 'unknown'] = (stats.statusBySource[job.site || 'unknown'] || 0) + 1;

  if (!title || !job.fullLink) { stats.droppedOther++; continue; }
  if (STUDENT.some(re => re.test(title + ' ' + company))) { stats.droppedStudent++; continue; }

  const companyHit = DEFENSE_COMPANY.find(re => re.test(company));
  const textHit = DEFENSE_TEXT.find(re => re.test(title + ' ' + company + ' ' + desc));
  if (companyHit || textHit) {
    stats.droppedDefense++;
    if (stats.defenseExamples.length < 6) {
      stats.defenseExamples.push(`${title} @ ${company} (${(companyHit || textHit).source.slice(0, 32)})`);
    }
    continue;
  }

  const key = title.toLowerCase() + '|' + company.toLowerCase();
  if (seenKeys.has(key)) { stats.droppedOther++; continue; }
  seenKeys.add(key);

  result.push({
    jobId: job.jobId || '',
    title,
    company,
    location: job.location || '',
    link: job.fullLink || '',
    fullLink: job.fullLink || '',
    site: job.site || '',
    description: (desc || title).slice(0, 3000),
    postedTime: job.postedTime || new Date().toISOString(),
  });
}
stats.kept = result.length;
return [{ jobs: result, stats: stats }];

const cvContext = $node['📄 结构化 CV 文本'].json.cvText || '';
const job = $json;
const jt = (job.title || '').replace(/"/g,'');
const co = (job.company || '').replace(/"/g,'');
const lk = (job.link || job.fullLink || '').replace(/"/g,'');
const lo = (job.location || '').replace(/"/g,'');
const desc = (job.description || job.title || '').replace(/"/g,'');
const pt = (job.postedTime || '').replace(/"/g,'');
const ji = (job.jobId || '').replace(/"/g,'');
const si = (job.site || '').replace(/"/g,'');

const meta = JSON.stringify({title:jt,company:co,link:lk,location:lo,postedTime:pt,jobId:ji,site:si});

const prompt = `你是一个专业的招聘匹配顾问。请根据候选人的CV和岗位信息评估匹配度。

## 原始数据（请原样返回）
__META__${meta}__META_END__

${cvContext}

### 岗位信息
**职位**: ${jt}
**公司**: ${co}
**地点**: ${lo || '慕尼黑/巴伐利亚'}
**描述**: ${desc || jt}

### 评分标准

| 维度 | 分值范围 | 评分指引 |
|------|---------|---------|
| background_match | 0-10 | 领域/行业匹配度：10=岗位行业与候选人CV专业领域完全吻合；6-9=相关或可转移领域；0=完全不相关 |
| skills_overlap | 0-25 | 技能重叠度：对比CV和岗位描述中的技术栈、工具、方法论。匹配项越多、深度越深分数越高 |
| experience_relevance | 0-25 | 经验相关性：候选人的项目/工作经历是否与岗位职责和要求匹配。考虑相关性和经验深度 |
| seniority | 0-10 | 资历匹配：10=完美匹配当前经验层级；5=中等；0=完全不匹配 |
| language_requirement | 0-10 | 语言要求：10=岗位接受候选人的语言能力（德语C1+英语C1）；5=部分匹配；0=不匹配 |
| location_match | 0-10 | 地点匹配 |
| bonus | 0-10 | 公司声誉、发展前景、福利待遇 |：10=慕尼黑或周边30km；8=巴伐利亚州/Hybrid；5=德国其他/Remote；0=国外 |

总分 overall = background_match + skills_overlap + experience_relevance + seniority + language_requirement + location_match + bonus
- Automotive 行业: background_match 扣 5 分

- Defense/Aerospace/国防 行业的岗位已被自动化过滤，不会出现在结果中

### 推荐分类
- overall >= 75 → "高度符合"
- overall >= 60 → "可以尝试"
- overall < 60 → "不适合"

### 输出格式（严格JSON，不要额外内容）
{
  "score": { "overall": 82, "background_match": 8, "skills_overlap": 20, "experience_relevance": 22, "seniority": 8, "language_requirement": 8, "location_match": 10, "bonus": 6 },
  "recommendation": "高度符合",
  "industry": "Automotive",
  "reason": "简短匹配理由",
  "_meta": ${meta}
}`;

return [{ prompt: prompt }];

const raw = $json?.choices?.[0]?.message?.content   // OpenCode Go / OpenAI-compatible response
  || $json.text || $json.output || $json.response || JSON.stringify($json);
let scoreData;
try { scoreData = JSON.parse(raw); }
catch(e) {
  try { const m = raw.match(/\{[\s\S]*\}/); if (m) scoreData = JSON.parse(m[0]); }
  catch(e2) { scoreData = {}; }
}

if (!scoreData || !scoreData.score) {
  scoreData = { score:{overall:50}, recommendation:'不适合', industry:'Other', reason:'解析失败', _meta:{} };
}

const s = scoreData.score || {};
const overall = s.overall !== undefined ? s.overall : 50;

const meta = scoreData._meta || {};
const title = meta.title || $json.title || '';
const company = meta.company || $json.company || '';
const link = meta.link || $json.link || '';
const location = meta.location || $json.location || '';
const postedTime = meta.postedTime || $json.postedTime || new Date().toISOString();
const site = meta.site || $json.site || '';
const jobId = meta.jobId || $json.jobId || '';

let r = scoreData.recommendation || '';
if (!r) {
  if (overall >= 75) r = '高度符合';
  else if (overall >= 60) r = '可以尝试';
  else r = '不适合';
}

let ml = '';
if (r === '高度符合') ml = '⭐ 高度符合';
else if (r === '可以尝试') ml = '💪 可以尝试';
else ml = '❌ 不适合';

// 第二道关卡：即使模型放行了军工/国防岗位，也在这里判 0 分丢弃
const DEF_VERDICT = /defen[cs]e|militar|wehr|r[uü]stung|armament|bundeswehr|nato/i;
const isDefense = DEF_VERDICT.test(String(scoreData.industry || ''));
const displayScore = isDefense ? 0 : Math.round(overall) / 10;
if (isDefense) { r = '不适合'; ml = '❌ 不适合（军工/国防）'; }

return [{ jobId, title, company, location, link, site, defenseBlocked: isDefense,
  description: $json.description || '',
  postedTime, score: displayScore,
  recommendation: r, matchLevel: ml,
  reason: scoreData.reason || '',
  industry: scoreData.industry || 'Other',
  skillMatch: s.skills_overlap ? Math.round(s.skills_overlap/2.5) : 5,
  industryMatch: s.background_match || 5,
  levelMatch: s.seniority || 5,
  locationMatch: s.location_match || 5,
  languageMatch: s.language_requirement || 5
}];

// Sort scored jobs, count how many get written, keep the top 10 for Notion.
const items = $input.all();
items.sort((a, b) => (b.json.score || 0) - (a.json.score || 0));
const scored = items.length;
const keep = items.slice(0, 10);
const above = keep.filter(i => (i.json.score || 0) >= 6).length;
return keep.map((i, idx) => ({
  ...i.json,
  _rank: idx + 1,
  _scoredTotal: scored,
  _writtenEstimate: above,
  _top: items[0] ? `${items[0].json.title} @ ${items[0].json.company} (${items[0].json.score})` : '',
}));

// Cross-run dedupe: drop postings that are already in the Notion database.
// NOTE: n8n's Notion node flattens properties to `property_<name>` keys (property_link,
// property_job_title, ...) and `url` is the Notion page URL - so scan every nested value.
const existing = new Set();
const existingIds = new Set();

const norm = (u) => String(u || '').split('?')[0].replace(/\/+$/, '').toLowerCase();
const harvest = (v, urls, ids, depth = 0) => {
  if (v === null || v === undefined || depth > 6) return;
  if (typeof v === 'string') {
    if (/^https?:\/\//i.test(v)) urls.push(v);
    else if (/^[a-z]+:[^\s]{6,}$/.test(v)) ids.push(v);
    return;
  }
  if (typeof v !== 'object') return;
  if (Array.isArray(v)) { v.forEach(x => harvest(x, urls, ids, depth + 1)); return; }
  for (const [k, val] of Object.entries(v)) {
    if (/job_?id|refnr|referenz/i.test(k) && typeof val === 'string') ids.push(val);
    harvest(val, urls, ids, depth + 1);
  }
};

let rows = 0;
for (const item of $input.all()) {
  const j = item.json || {};
  if (!Object.keys(j).length) continue;               // alwaysOutputData placeholder row
  rows++;
  const urls = [], ids = [];
  harvest(j, urls, ids);
  for (const u of urls) {
    existing.add(norm(u));
    const li = u.match(/\/jobs\/view\/(\d+)/);
    if (li) existingIds.add('linkedin:' + li[1]);
    const ba = u.match(/jobdetail\/([^/?#]+)/);
    if (ba) existingIds.add('ba:' + decodeURIComponent(ba[1]));
    const baRef = u.match(/(\d{3,6}-\d{6,12}-S)/);
    if (baRef) existingIds.add('ba:' + baRef[1]);
  }
  for (const i of ids) existingIds.add(String(i).trim());
}

const upstream = $('📋 解析岗位列表').first().json;
const jobs = upstream.jobs || [];
const stats = Object.assign({}, upstream.stats || {});
const fresh = [];
const skipped = [];

for (const job of jobs) {
  const link = norm(job.fullLink);
  const jid = job.jobId || '';
  const dup = (link && existing.has(link)) || (jid && existingIds.has(jid));
  if (dup) { skipped.push(job.title + ' @ ' + job.company); continue; }
  fresh.push(job);
}
stats.alreadyInNotion = skipped.length;
stats.existingRows = rows;
stats.newJobs = fresh.length;
stats.skippedExamples = skipped.slice(0, 5);
return [{ jobs: fresh, stats: stats }];

