={{ (() => {
  const st = $('🔁 过滤已存在').first().json.stats || {};
  const w = $('📊 排序+Top10').first().json || {};
  const src = st.sources || {};
  const errs = (st.errors || []).slice(0, 3);
  const lines = [
    '🤖 求职自动化完成',
    `抓取 ${st.raw || 0} 个岗位 (BA ${src.arbeitsagentur || 0} / LinkedIn ${src.linkedin || 0} / Indeed ${src.indeed || 0})`,
    `过滤：实习/学生 ${st.droppedStudent || 0} · 军工国防 ${st.droppedDefense || 0}`,
    `Notion 已存在跳过 ${st.alreadyInNotion || 0}`,
    `本次新岗位 ${st.newJobs || 0} → 打分完成 → 入库 ${w.written || '?'} 条`,
  ];
  if (w.top) lines.push('最高分：' + w.top);
  if (st.defenseExamples && st.defenseExamples.length) lines.push('已跳过(军工示例)：' + st.defenseExamples.slice(0, 3).join(' | '));
  if (errs.length) lines.push('⚠️ 抓取告警：' + errs.join(' | '));
  return lines.join('\n');
})() }}
